// Stage -> background music. Falls back to fightMusic for unmapped stages.
const levelMusicMap = {
  'CLASSIC': fightMusic,
  'THE TEMPLE': templeFightMusic,
};

const MUSIC_VOLUME = 0.35;
[titleMusic, fightMusic, templeFightMusic].forEach(m => m.volume = MUSIC_VOLUME);

let currentFightMusic = null;

function playTitleMusic() {
  stopFightMusic();
  if (titleMusic.paused) {
    titleMusic.play().catch(() => {});
  }
}

function stopTitleMusic() {
  if (!titleMusic.paused) {
    titleMusic.pause();
    titleMusic.currentTime = 0;
  }
}

function playFightMusic(levelName) {
  stopFightMusic();
  const music = levelMusicMap[levelName] || fightMusic;
  music.currentTime = 0;
  music.play().catch(() => {});
  currentFightMusic = music;
}

function stopFightMusic() {
  if (currentFightMusic && !currentFightMusic.paused) {
    currentFightMusic.pause();
    currentFightMusic.currentTime = 0;
  }
  currentFightMusic = null;
}

