      sunGrad.addColorStop(0.25, 'rgba(255,230,140,0.7)');
      sunGrad.addColorStop(0.6, 'rgba(255,200,80,0.2)');
      sunGrad.addColorStop(1, 'rgba(255,180,50,0)');
      ctx.fillStyle = sunGrad;
      ctx.fillRect(730, 0, 180, 180);
